CREATE TABLE IF NOT EXISTS users (email TEXT PRIMARY KEY, name TEXT, role TEXT NOT NULL DEFAULT 'member', active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS login_codes (email TEXT PRIMARY KEY, code_hash TEXT NOT NULL, expires_at INTEGER NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, sent_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, email TEXT NOT NULL, expires_at INTEGER NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS entities (id TEXT PRIMARY KEY, name TEXT NOT NULL, country TEXT, details TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS businesses (id TEXT PRIMARY KEY, name TEXT NOT NULL, entity_id TEXT, kind TEXT NOT NULL DEFAULT 'general', status TEXT NOT NULL DEFAULT 'activo', description TEXT, sort INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS platforms (id TEXT PRIMARY KEY, name TEXT NOT NULL, region TEXT, business_id TEXT, status TEXT NOT NULL DEFAULT 'sin_cuenta', sort INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS policies (id TEXT PRIMARY KEY, platform_id TEXT, title TEXT NOT NULL, happened_on TEXT, url TEXT, notes TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS suppliers (id TEXT PRIMARY KEY, business_id TEXT NOT NULL, name TEXT NOT NULL, kind TEXT, contact_name TEXT, email TEXT, phone TEXT, website TEXT, brands TEXT, min_order TEXT, payment_terms TEXT, brand_auth TEXT NOT NULL DEFAULT 'pendiente', platforms TEXT NOT NULL DEFAULT '[]', notes TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS files (id TEXT PRIMARY KEY, r2_key TEXT NOT NULL, filename TEXT NOT NULL, mime TEXT NOT NULL, size INTEGER NOT NULL, original_size INTEGER, uploaded_by TEXT, uploaded_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS company_docs (id TEXT PRIMARY KEY, group_id TEXT NOT NULL, entity_id TEXT NOT NULL, folder TEXT NOT NULL, title TEXT NOT NULL, issued_on TEXT, expires_on TEXT, file_id TEXT, notes TEXT, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS invoices (id TEXT PRIMARY KEY, business_id TEXT NOT NULL, supplier_id TEXT, file_id TEXT, kind TEXT NOT NULL DEFAULT 'factura', title TEXT, invoice_number TEXT, po_number TEXT, issue_date TEXT, due_date TEXT, currency TEXT DEFAULT 'USD', subtotal REAL, tax REAL, shipping REAL, discount REAL, total REAL, payment_status TEXT DEFAULT 'pendiente', payment_method TEXT, platforms TEXT NOT NULL DEFAULT '[]', supplier_name TEXT, supplier_address TEXT, supplier_tax_id TEXT, buyer_name TEXT, buyer_address TEXT, items TEXT NOT NULL DEFAULT '[]', extracted TEXT, confidence TEXT, read_by TEXT, status TEXT NOT NULL DEFAULT 'por_revisar', created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS inv_biz_date ON invoices(business_id, issue_date);
CREATE INDEX IF NOT EXISTS inv_sup ON invoices(supplier_id);
CREATE TABLE IF NOT EXISTS deadlines (id TEXT PRIMARY KEY, title TEXT NOT NULL, entity_id TEXT, due_on TEXT NOT NULL, notes TEXT, done INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS records (id TEXT PRIMARY KEY, business_id TEXT NOT NULL, tool TEXT NOT NULL, data TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS recipients (email TEXT PRIMARY KEY, label TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sends (id TEXT PRIMARY KEY, to_email TEXT NOT NULL, subject TEXT, items TEXT NOT NULL, sent_by TEXT, sent_at TEXT NOT NULL, ok INTEGER NOT NULL DEFAULT 1, error TEXT);
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT);
CREATE TABLE IF NOT EXISTS dev_outbox (id TEXT PRIMARY KEY, to_email TEXT, subject TEXT, raw TEXT, created_at TEXT);
CREATE TABLE IF NOT EXISTS tax_obligations (id TEXT PRIMARY KEY, entity_id TEXT NOT NULL, name TEXT NOT NULL, agency TEXT, account_id TEXT, frequency TEXT NOT NULL DEFAULT 'trimestral', due_day INTEGER NOT NULL DEFAULT 20, due_offset INTEGER NOT NULL DEFAULT 1, start_date TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, source_doc_id TEXT, notes TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS tax_periods (id TEXT PRIMARY KEY, obligation_id TEXT NOT NULL, label TEXT NOT NULL, period_start TEXT NOT NULL, period_end TEXT NOT NULL, due_date TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pendiente', amount REAL, filed_on TEXT, return_file_id TEXT, payment_file_id TEXT, notes TEXT, created_at TEXT NOT NULL, UNIQUE(obligation_id, period_start));
CREATE TABLE IF NOT EXISTS scan_items (id TEXT PRIMARY KEY, business_id TEXT NOT NULL, name TEXT NOT NULL, code TEXT, stores TEXT, ceiling REAL, ceiling_app REAL, ceiling_note TEXT, max_units INTEGER, risk TEXT, list TEXT NOT NULL DEFAULT 'prioritario', purpose TEXT, ficha TEXT, source TEXT, sort INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS scan_logs (id TEXT PRIMARY KEY, business_id TEXT NOT NULL, item_id TEXT, name TEXT, code TEXT, store TEXT, can_sell TEXT, amazon_sells TEXT, buybox TEXT, buybox_price REAL, drops TEXT, hazmat TEXT, size_ok TEXT, shelf_price REAL, limit_price REAL, verdict TEXT, reasons TEXT, notes TEXT, file_id TEXT, user_email TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS cards (id TEXT PRIMARY KEY, nickname TEXT NOT NULL, issuer TEXT, network TEXT, holder TEXT, last4 TEXT NOT NULL, exp_month INTEGER, exp_year INTEGER, owner TEXT NOT NULL DEFAULT 'personal', entity_id TEXT, closing_day INTEGER, due_day INTEGER, credit_limit REAL, notes TEXT, active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS card_cycles (id TEXT PRIMARY KEY, card_id TEXT NOT NULL, closing_date TEXT NOT NULL, due_date TEXT NOT NULL, paid INTEGER NOT NULL DEFAULT 0, paid_on TEXT, amount REAL, file_id TEXT, created_at TEXT NOT NULL, UNIQUE(card_id, closing_date));
CREATE TABLE IF NOT EXISTS lots (id TEXT PRIMARY KEY, business_id TEXT NOT NULL, name TEXT NOT NULL, stage TEXT NOT NULL DEFAULT 'comprado', dates TEXT NOT NULL DEFAULT '{}', shipment_id TEXT, notes TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS payouts (id TEXT PRIMARY KEY, business_id TEXT NOT NULL, lot_id TEXT, paid_on TEXT NOT NULL, amount REAL NOT NULL, notes TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS tool_links (id TEXT PRIMARY KEY, business_id TEXT NOT NULL, name TEXT NOT NULL, url TEXT NOT NULL, description TEXT, sort INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS amazon_cases (id TEXT PRIMARY KEY, business_id TEXT NOT NULL, title TEXT NOT NULL, case_number TEXT, kind TEXT, due_date TEXT, status TEXT NOT NULL DEFAULT 'abierto', invoice_ids TEXT NOT NULL DEFAULT '[]', doc_ids TEXT NOT NULL DEFAULT '[]', notes TEXT, sent_at TEXT, sent_to TEXT, created_at TEXT NOT NULL);
